"""A single-file, offline STTRPSD comparison report with an SVG route explorer."""
from __future__ import annotations

import html
import json
from pathlib import Path

from ._branding import BRAND_IMAGE_DATA_URI


def write_report(data: dict, path: str | Path) -> None:
    """Write HTML with inline data, CSS and JavaScript; no network resources."""
    payload = json.dumps(data, ensure_ascii=False, allow_nan=False)
    # JSON inside a script tag requires HTML-aware escaping, even when that
    # script has application/json type. Do not let a solver name end the tag.
    payload = (payload.replace("&", "\\u0026").replace("<", "\\u003c")
               .replace(">", "\\u003e").replace("\u2028", "\\u2028")
               .replace("\u2029", "\\u2029"))
    title = html.escape(str(data.get("title", "STTRPSD benchmark comparison")))
    page = (TEMPLATE.replace("__BRAND_IMAGE__", BRAND_IMAGE_DATA_URI)
            .replace("__TITLE__", title).replace("__DATA__", payload))
    Path(path).write_text(page, encoding="utf-8")


